window.BANK=window.BANK||{};window.BANK["7859"]={"n":"第三章单选 社会主义改造理论","qs":[{"i":"161980","t":"单选","q":"五种经济成分中，在国民经济中居于领导地位的是","o":{"A":"A.国营经济","B":"B.个体经济","C":"C.国家资本主义经济","D":"D.私人资本主义经济"},"a":"A","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P114考点11拓展与点拨</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">五种经济成分中，<strong>主要的经济成分是三种:社会主义经济、个体经济和资本主义经济。</strong>其中，国营经济<strong>居于领导地位</strong>，个体经济占<strong>绝对优势</strong>。<strong>个体经济是处于&ldquo;十字路口&rdquo;的经济。过渡性质的经济成分有两种</strong>:半社会主义性质的合作社经济、国家资本主义经济。</span></p>\n<p><strong>简析：</strong>A正确。农民和手工业者的个体经济在新民主主义社会的五种经济成分中占绝对优势，但不居于领导地位，B错误，C、D两项也是错误选项。</p>","k":"考点14：新民主主义社会是一个过渡性的社会","kid":"212","r":516,"tot":575},{"i":"161981","t":"单选","q":"建国初期，随着全国土地改革的基本完成，国内的主要矛盾是","o":{"A":"A.人民大众同帝国主义、封建主义和国民党反动派残余势力之间的矛盾","B":"B.工人阶级和资产阶级的矛盾","C":"C.生产力与生产关系的矛盾和经济基础与上层建筑的矛盾","D":"D.人民日益增长的物质文化需要同落后的社会生产之间的矛盾"},"a":"B","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P114考点11-1-5</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">主要矛盾:随着土地改革的基本完成(1952年底)，工人阶级和资产阶级的矛盾逐步成为国内的主要矛盾。</span></p>\n<p><strong>简析：</strong>B正确。A是新中国成立至全国土地改革基本完成期间国内的主要矛盾；C是社会基本矛盾；D是社会主义改造完成后中国社会的主要矛盾。点拨题干的意思是说土改基本完成(1952年底)之后国内的主要矛盾，不是土改完成之前的主要矛盾。</p>","k":"考点14：新民主主义社会是一个过渡性的社会","kid":"212","r":331,"tot":632},{"i":"161982","t":"单选","q":"党在过渡时期总路线的主要内容被概括为“一化三改”,也曾被比喻为鸟的“主体”和“两翼”。“主体”是指","o":{"A":"A.对农业的社会主义改造","B":"B.对手工业的社会主义改造","C":"C.对资本主义工商业的社会主义改造","D":"D.社会主义工业化"},"a":"D","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P115考点11-2-2</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">总路线的内容:&ldquo;一化三改&rdquo;。&ldquo;一化&rdquo;即社会主义工业化，&ldquo;三改&rdquo;是对个体农业、手工业和资本主义工商业的社会主义改造。&ldquo;一化&rdquo;是&ldquo;主体&rdquo;，&ldquo;三改&rdquo;是&ldquo;两翼&rdquo;</span></p>\n<p><strong>简析：</strong>&ldquo;主体&rdquo;是指社会主义工业化，对个体农业、手工业和资本主义工商业的社会主义改造是&ldquo;两翼&rdquo;。D正确，A、B、C错误。</p>","k":"考点15：党在过渡时期的总路线及其理论依据","kid":"213","r":466,"tot":558},{"i":"161983","t":"单选","q":"农业社会主义改造遵循的原则是","o":{"A":"A.积极领导、稳步前进","B":"B.区别对象、积极引导、逐步过渡","C":"C.自愿互利、典型示范和国家帮助","D":"D.既反保守又反冒进"},"a":"C","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P115考点12-1-2</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">1.对农业的社会主义改造(三大改造中首先进行的改造，通过合作化把个体经济改造为集体经济)</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">遵循自愿互利、典型示范和国家帮助的原则。(原则)</span></p>\n<p><strong>简析：</strong>以毛泽东同志为主要代表的中国共产党人开辟了一条适合我国情况的农业社会主义改造道路：①积极引导农民组织起来，走互助合作道路。2遵循自愿互利、典型示范和国家帮助的原则，以互助合作的优越性吸引农民走互助合作道路。③正确分析农村的阶级和阶层状况，制定正确的阶级政策。④坚持积极领导、稳步前进的方针。⑤采取循序渐进的步骤。C正确。</p>\n<p>点拨：①对手工业的社会主义改造，党和政府采取了&ldquo;积极领导、稳步前进&rdquo;的方针。(&ldquo;中国近现代史纲要&rdquo;课程中对这个方针的表述为&ldquo;积极引导、稳步前进&rdquo;)②我国对农业、手工业和资本主义工商业的改造，都采取了区别对象、积极引导、逐步过渡的方式。③党的八大坚持党中央提出的既反保守又反冒进，即在综合平衡中稳步前进的经济建设方针。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":410,"tot":578},{"i":"161984","t":"单选","q":"在农业合作化进程中，具有半社会主义性质的组织形式是","o":{"A":"A.临时互助组","B":"B.常年互助组","C":"C.初级合作社","D":"D.高级合作社"},"a":"C","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P116考点12表格</span></strong></p>\n<p><img src=\"data:image/png;base64,\" alt=\"\" /></p>\n<p><strong>简析：</strong>互助组(包括临时互助组和常年互助组两种形式)不涉及生产资料问题，只是在生产方面组织起来、互帮互助，是农业合作化的最初过渡形式，具有社会主义萌芽性质。初级农业生产合作社以土地入股和统一经营为特点，实行集体劳动，产品分配采取按劳分配和土地入股分红相结合，具有半社会主义性质。高级农业生产合作社实行生产资料农民集体所有，实行按劳分配，具有完全的社会主义性质。C正确。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":477,"tot":544},{"i":"161985","t":"单选","q":"在实行个别企业的公私合营中，企业利润分配上采取的办法是","o":{"A":"A.定股定息","B":"B.“四马分肥”","C":"C.和平赎买","D":"D.公私兼顾"},"a":"B","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P116考点12-3-(2)</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">采取从低级到高级的国家资本主义的过渡形式(步骤)</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第一步</strong>实行初级形式的国家资本主义(委托加工、计划订货、统购包销、经销代销等)。<strong>企业具有了社会主义的因素</strong>。第二步实行个别企业的公私合营。<strong>企业属于半社会主义性质。第三步</strong>实行全行业的公私合营。全行业公私合营后，企业生产资料为国家所有，<strong>基本上成为社会主义国营性质。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">第一步初级形式的国家资本主义，<strong>主要是同资本家在企业外部的合作</strong>。第二步个别企业的公私合营，是<strong>社会主义成分同资本主义成分在企业内部的合作。企业的利润分配，在第一步、第二步，都实行&ldquo;四马分肥&rdquo;，即按国家所得税、企业公积金、工人福利费、资方红利这四个方面进行分配。第三步，国家对合营企业进行清产核资、定股定息。</strong>从个别企业的公私合营到全行业公私合营，是党和国家对资本主义工商业<strong>采取利用、限制、改造政策的必然趋势</strong>，也是经济运行中<strong>计划不断强化的必然结果</strong>。它能更好地从全局出发有计划地安排生产,保证国家重点建设的顺利进行。</span></p>\n<p><strong>简析：</strong>对资本主义工商业的社会主义改造，第二步实行个别企业的公私合营，国家向私营企业投资入股，企业的生产资料由国家和资本家共同所有；企业利润的分配仍为&ldquo;四马分肥&rdquo;。B正确。点拨对资本主义工商业的社会主义改造经历了三个步骤。其中，第一步(初级形式的国家资本主义)和第二步(个别企业的公私合营)的企业利润分配都是&ldquo;四马分肥&rdquo;。第三步(全行业的公私合营)在分配上实行定股定息。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":465,"tot":554},{"i":"161986","t":"单选","q":"我国对资本主义工商业的社会主义改造，采取了从低级到高级的国家资本主义的过渡形式。其中第二步主要实行个别企业的公私合营，这些企业的性质","o":{"A":"A.仍然是资本主义性质的企业","B":"B.是具有了社会主义因素的企业","C":"C.是半社会主义性质的企业","D":"D.是社会主义国营性质的企业"},"a":"C","j":"<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P116考点12-3-(2)</span></strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">采取从低级到高级的国家资本主义的过渡形式(步骤)</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第一步</strong>实行初级形式的国家资本主义(委托加工、计划订货、统购包销、经销代销等)。<strong>企业具有了社会主义的因素</strong>。第二步实行个别企业的公私合营。<strong>企业属于半社会主义性质。第三步</strong>实行全行业的公私合营。全行业公私合营后，企业生产资料为国家所有，<strong>基本上成为社会主义国营性质。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">第一步初级形式的国家资本主义，<strong>主要是同资本家在企业外部的合作</strong>。第二步个别企业的公私合营，是<strong>社会主义成分同资本主义成分在企业内部的合作。企业的利润分配，在第一步、第二步，都实行&ldquo;四马分肥&rdquo;，即按国家所得税、企业公积金、工人福利费、资方红利这四个方面进行分配。第三步，国家对合营企业进行清产核资、定股定息。</strong>从个别企业的公私合营到全行业公私合营，是党和国家对资本主义工商业<strong>采取利用、限制、改造政策的必然趋势</strong>，也是经济运行中<strong>计划不断强化的必然结果</strong>。它能更好地从全局出发有计划地安排生产,保证国家重点建设的顺利进行。</span></p>\n<p><strong>简析：</strong>对资本主义工商业的社会主义改造，第二步实行个别企业的公私合营，企业的生产资料由国家和资本家共同所有，国家派干部(公方代表)进入企业内部，根据国家建设需要，同工人、资本家(私方代表)共同管理和改造企业，公方代表居领导地位。企业利润的分配仍为&ldquo;四马分肥&rdquo;,资本家的剥削进一步受到限制。企业的经营管理以发展生产、满足人民需要和完成国家计划为目标，因而已经属于半社会主义性质的企业，C正确。A、B、D不符合题意。点拨从企业性质的角度来说，三步分别对应：&ldquo;具有了社会主义的因素&rdquo;&ldquo;属于半社会主义性质&rdquo;&ldquo;基本上成为社会主义国营性质&rdquo;。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":427,"tot":548},{"i":"161987","t":"单选","q":"我国对资本主义工商业的社会主义改造经历了三个步骤。同资本家在企业外部的合作是指","o":{"A":"A.实行初级形式的国家资本主义","B":"B.实行个别企业的公私合营","C":"C.实行全行业的公私合营","D":"D.实行“四马分肥”"},"a":"A","j":"<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P116考点12-3-(2)</span></strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">采取从低级到高级的国家资本主义的过渡形式(步骤)</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第一步</strong>实行初级形式的国家资本主义(委托加工、计划订货、统购包销、经销代销等)。<strong>企业具有了社会主义的因素</strong>。第二步实行个别企业的公私合营。<strong>企业属于半社会主义性质。第三步</strong>实行全行业的公私合营。全行业公私合营后，企业生产资料为国家所有，<strong>基本上成为社会主义国营性质。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">第一步初级形式的国家资本主义，<strong>主要是同资本家在企业外部的合作</strong>。第二步个别企业的公私合营，是<strong>社会主义成分同资本主义成分在企业内部的合作。企业的利润分配，在第一步、第二步，都实行&ldquo;四马分肥&rdquo;，即按国家所得税、企业公积金、工人福利费、资方红利这四个方面进行分配。第三步，国家对合营企业进行清产核资、定股定息。</strong>从个别企业的公私合营到全行业公私合营，是党和国家对资本主义工商业<strong>采取利用、限制、改造政策的必然趋势</strong>，也是经济运行中<strong>计划不断强化的必然结果</strong>。它能更好地从全局出发有计划地安排生产,保证国家重点建设的顺利进行。</span></p>\n<p><strong>简析：</strong>第一步实行初级形式的国家资本主义。国家在私营工业中实行委托加工、计划订货、统购包销，这主要是同资本家在企业外部的合作。第二步实行个别企业的公私合营。这是社会主义成分同资本主义成分在企业内部的合作。第三步实行全行业的公私合营。全行业公私合营后，国家对合营企业进行清产核资、定股定息，委派人员负责企业的生产经营管理，统一调配企业的人、财、物，生产资料为国家所有。全行业公私合营后，企业的生产关系已经发生了根本的变化，基本上成为社会主义国营性质的企业。A正确，B、C错误。&ldquo;四马分肥&rdquo;既是实行初级形式的国家资本主义企业的分配政策，也是个别企业的公私合营的分配政策，D也错误。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":301,"tot":603},{"i":"161988","t":"单选","q":"之所以说我国社会主义改造的基本完成是一个伟大的历史性胜利，是因为如此复杂、困难和深刻的社会变革①没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展②没有追求纯粹的单一的社会主义经济成分，反而深刻认识到在社会主义改造基本完成以后，公有制经济可以和非公有制经济共同发展③没有引起巨大的社会动荡，反而极大地加强了人民的团结④没有导致对什么是社会主义的理解产生混乱，反而在此过程中形成了对我国社会主义发展阶段问题的科学理论","o":{"A":"A.①②","B":"B.②③","C":"C.①③","D":"D.②④"},"a":"C","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P117考点12-5</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">我国社会主义改造的基本完成是一个伟大的历史性胜利</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>一是</strong>在一个几亿人口的大国中比较顺利地实现了如此复杂、困难和深刻的社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展;<strong>二是</strong>这样的变革没有引起巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民普遍拥护的情况下完成的。</span></p>\n<p><strong>简析：</strong>在我国社会主义改造的历史上，有两个事实是在世界历史上各种革命大变动中罕见的：一是在一个几亿人口的大国中比较顺利地实现了如此复杂、困难和深刻的社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展；二是这样的变革没有引起巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民普遍拥护的情况下完成的。这些情况说明，我国社会主义改造的基本完成是一个伟大的历史性胜利，是中国共产党紧紧依靠人民所作出的伟大创造。①③正确。我国的社会主义改造取得了历史性的胜利，同时，也出现了一些失误和偏差。出现这些问题，既有指导思想上急于求成、不够谨慎以及工作方法上过于简单等因素，也有受当时历史条件限制而产生的认识上的一些问题，主要是：在社会主义经济模式的选择和理解上过于单一，追求纯粹的单一的社会主义经济成分，在公有制实现形式的选择和理解上过于简单化，只注意到集体所有制和全民所有制这两种基本形式，而对社会主义改造基本完成以后公有制经济可以和非公有制经济共同发展缺乏认识。党在实际工作过程中曾对这些问题有所觉察，对某些失误和偏差也做过纠正，但毕竟认识不深。更重要的是，当时党对我国社会主义发展阶段问题还没有形成科学的理论，对什么是社会主义还没有完全搞清楚，致使一些遗留问题长期没有得到解决。②④错误。因此，本题选C。</p>","k":"考点16：社会主义改造道路和历史经验","kid":"214","r":399,"tot":567}]};
